<?php
declare(strict_types=1);
namespace Modules\Ecommerce\Models;
use App\Models\Concerns\Auditable; use App\Models\Concerns\UsesTenantConnection; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Product extends Model { use Auditable, SoftDeletes, UsesTenantConnection; protected $table='ecommerce_products'; protected $fillable=['category_id','name','slug','sku','barcode','description','feature_image','cost_price','sale_price','compare_at_price','tax_rate','stock_quantity','low_stock_threshold','track_inventory','is_active','is_featured','weight','dimensions','created_by']; protected function casts(): array{return ['cost_price'=>'decimal:2','sale_price'=>'decimal:2','compare_at_price'=>'decimal:2','tax_rate'=>'decimal:2','stock_quantity'=>'integer','low_stock_threshold'=>'integer','track_inventory'=>'boolean','is_active'=>'boolean','is_featured'=>'boolean','weight'=>'decimal:3','dimensions'=>'array'];} public function category(): BelongsTo{return $this->belongsTo(Category::class);} public function images(): HasMany{return $this->hasMany(ProductImage::class)->orderBy('sort_order');} }
